const fs = require('fs');
let text = fs.readFileSync('app/admin/page.tsx', 'utf-8');
const lines = text.split('\n');
const startIdx = lines.findIndex(l => l.includes("activeTab === 'cms'"));

let endIdx = -1;
if (startIdx > -1) {
    endIdx = lines.findIndex((l, i) => i > startIdx && l.includes("activeTab === 'general'"));
}

if (startIdx > -1 && endIdx > -1) {
    lines.splice(startIdx, endIdx - startIdx);
    fs.writeFileSync('app/admin/page.tsx', lines.join('\n'));
    console.log("Removed CMS tab content. Lines removed:", endIdx - startIdx);
}

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  const requestHeaders = new Headers(request.headers);
  requestHeaders.set('x-pathname', request.nextUrl.pathname);

  return NextResponse.next({
    request: {
      headers: requestHeaders,
    },
  });
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico|_next|api|assets).*)'],
};

