            const fromIndex = order.indexOf(sourceId);
            const toIndex = order.indexOf(targetId);

            if (fromIndex === -1 || toIndex === -1) {
                return current;
            }

            order.splice(fromIndex, 1);
            order.splice(toIndex, 0, sourceId);
            return { ...current, sectionOrder: order };
