          ...workflow,
          draft,
          updatedAt: new Date().toISOString(),
        },
      };

      const writeError = await writeStore(nextStore);
      if (writeError) {
        return NextResponse.json({ error: 'Failed to write draft to Supabase: ' + writeError.message }, { status: 500 });
      }

      return NextResponse.json({
        success: true,
        action,
        profile: draft,
        workflow: {
          revisions: (nextStore._workflow?.revisions || []).map((revision) => ({
            id: revision.id,
            createdAt: revision.createdAt,
            type: revision.type,
          })),
          updatedAt: nextStore._workflow?.updatedAt || null,
          publishedAt: nextStore._workflow?.publishedAt || null,
        },
      });
    }

    if (action === 'publish') {
      let sourceDraft = workflow.draft;

      // Fallback in case saveDraft failed initially or DB was empty but they clicked saveAndPublish
      if (!sourceDraft || !validateProfilePayload(sourceDraft)) {
         sourceDraft = publishedProfile;
      }

      if (!sourceDraft || Object.keys(sourceDraft).length === 0) {
        return NextResponse.json({ error: 'No valid draft to publish. Please save a draft first or check the profile_data table configuration.' }, { status: 400 });
      }

      const nextPublishedProfile = preserveRuntimeMetrics(sourceDraft, publishedProfile);
      const nextRevisions = [...(workflow.revisions || []), buildRevision('publish', publishedProfile)]
        .slice(-MAX_REVISIONS);

      const nextStore: ProfileStore = {
        ...nextPublishedProfile,
        _workflow: {
          ...workflow,
          draft: nextPublishedProfile,
          revisions: nextRevisions,
          publishedAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      };

      const writeError = await writeStore(nextStore);
      if (writeError) {
         return NextResponse.json({ error: 'Failed to publish to Supabase: ' + writeError.message }, { status: 500 });
      }

      return NextResponse.json({
        success: true,
        action,
        profile: nextPublishedProfile,
        workflow: {
          revisions: nextRevisions.map((revision) => ({
            id: revision.id,
            createdAt: revision.createdAt,
            type: revision.type,
          })),
          updatedAt: nextStore._workflow?.updatedAt || null,
          publishedAt: nextStore._workflow?.publishedAt || null,
        },
      });
    }

    if (action === 'rollback') {
      const revisionId = isObject(payload) && typeof payload.revisionId === 'string' ? payload.revisionId : '';
      if (!revisionId) {
        return NextResponse.json({ error: 'revisionId is required for rollback' }, { status: 400 });
      }

      const targetRevision = (workflow.revisions || []).find((revision) => revision.id === revisionId);
      if (!targetRevision || !validateProfilePayload(targetRevision.snapshot)) {
        return NextResponse.json({ error: 'Revision not found or invalid' }, { status: 404 });
      }

      const rollbackProfile = preserveRuntimeMetrics(targetRevision.snapshot, publishedProfile);
      const nextRevisions = [
        ...(workflow.revisions || []),
        buildRevision('rollback', publishedProfile),
      ].slice(-MAX_REVISIONS);

      const nextStore: ProfileStore = {
        ...rollbackProfile,
        _workflow: {
          ...workflow,
          draft: rollbackProfile,
          revisions: nextRevisions,
          publishedAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      };

      const writeError = await writeStore(nextStore);
      if (writeError) {
         return NextResponse.json({ error: 'Failed to rollback on Supabase: ' + writeError.message }, { status: 500 });
      }

      return NextResponse.json({
        success: true,
        action,
        profile: rollbackProfile,
        workflow: {
          revisions: nextRevisions.map((revision) => ({
            id: revision.id,
            createdAt: revision.createdAt,
            type: revision.type,
          })),
          updatedAt: nextStore._workflow?.updatedAt || null,
          publishedAt: nextStore._workflow?.publishedAt || null,
        },
      });
    }

    return NextResponse.json({ error: 'Unsupported action' }, { status: 400 });
  } catch {
    return NextResponse.json({ error: 'Failed to save profile data' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { saveConfig } from '@/utils/config';
import { createClient } from '@supabase/supabase-js';

export async function POST(request: Request) {
  try {
    const { supabaseUrl, supabaseKey, adminUsername, adminPassword } = await request.json();

    if (!supabaseUrl || !supabaseKey || !adminUsername || !adminPassword) {
      return NextResponse.json({ error: 'All fields are required' }, { status: 400 });
    }

    // Save configuration out of bound bypassing Next.js env restrictions using APPDATA / HOME
    saveConfig({
      NEXT_PUBLIC_SUPABASE_URL: supabaseUrl,
      NEXT_PUBLIC_SUPABASE_ANON_KEY: supabaseKey
    });

    try {
      const supabase = createClient(supabaseUrl, supabaseKey);

      // Create an Admin account directly in Supabase Auth using a dummy email (skip real email setup)
      const fakeEmail = `${adminUsername}@aura.local`;
      const { error: authError } = await supabase.auth.signUp({
        email: fakeEmail,
        password: adminPassword,
      });

      if (authError && !authError.message.includes('already registered')) {
        console.warn('Supabase Auth error (might be expected if already setup):', authError.message);
      }

      const { error: tableCheck } = await supabase.from('profile_data').select('id').limit(1);

      if (tableCheck && tableCheck.code === 'PGRST116') {
        const { error: rpcError } = await supabase.rpc('setup_profile_table');
        if (rpcError) {
          console.warn('Could not auto-create tables via RPC', rpcError);
          const sql = `
-- 1. Create the profile_data table
CREATE TABLE IF NOT EXISTS profile_data (
  id text PRIMARY KEY,
  content jsonb NOT NULL DEFAULT '{}'::jsonb
);

-- 2. Enable Row Level Security (RLS)
ALTER TABLE profile_data ENABLE ROW LEVEL SECURITY;

-- 3. Safely recreate policies
DO $$
BEGIN
    DROP POLICY IF EXISTS "Allow public read access" ON profile_data;
    DROP POLICY IF EXISTS "Allow public write access" ON profile_data;
END $$;

CREATE POLICY "Allow public read access"
ON profile_data FOR SELECT
USING (true);

CREATE POLICY "Allow public write access"
ON profile_data FOR ALL
USING (true)
WITH CHECK (true);

-- 4. Force schema cache refresh (Fixes "schema cache is stale" error)
NOTIFY pgrst, 'reload schema';
          `.trim();
          return NextResponse.json({
            success: false,
            sqlRequired: true,
            sql,
            message: 'Account connected successfully, but the data table is missing. Please run the SQL code below in the Supabase "SQL Editor" to create the table.'
          });
        }
      }

    } catch (supaEx: any) {
      console.error('Supabase Setup Step Error:', supaEx.message);
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error('Setup Error:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';

const isDev = process.env.NODE_ENV !== 'production';

const reportServerError = (...args: unknown[]) => {
  if (isDev) {
    console.error(...args);
  }
};

export async function POST(req: NextRequest) {
  try {
    const formData = await req.formData();
    const file = formData.get('fileToUpload') as File;
    const userHash = formData.get('userhash') as string;

    if (!file || !userHash) {
      return NextResponse.json({ error: 'Missing file or userhash' }, { status: 400 });
    }

    // Re-construct FormData for the external request
    const backendFormData = new FormData();
    backendFormData.append('reqtype', 'fileupload');
    backendFormData.append('userhash', userHash);
    backendFormData.append('fileToUpload', file);

    const response = await fetch('https://catbox.moe/user/api.php', {
      method: 'POST',
      body: backendFormData,
    });

    if (!response.ok) {
      const errorText = await response.text();
      return NextResponse.json({ error: `Catbox API Error: ${errorText}` }, { status: response.status });
    }

    const url = await response.text();
    return new NextResponse(url, { status: 200 });

  } catch (error) {
    reportServerError('Upload proxy error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { writeFile, mkdir } from 'fs/promises';
import path from 'path';

const isDev = process.env.NODE_ENV !== 'production';

const reportServerError = (...args: unknown[]) => {
  if (isDev) {
    console.error(...args);
  }
};

export async function POST(req: NextRequest) {
  try {
    const formData = await req.formData();
    const file = formData.get('fileToUpload') as File;

    if (!file) {
      return NextResponse.json({ error: 'No file uploaded' }, { status: 400 });
    }

    const buffer = Buffer.from(await file.arrayBuffer());

    // Sanitize filename to prevent directory traversal and weird characters
    const sanitizedFilename = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
    const uniqueFilename = `${Date.now()}-${sanitizedFilename}`;

    // Ensure public/assets directory exists
    const uploadDir = path.join(process.cwd(), 'public', 'assets');
    try {
        await mkdir(uploadDir, { recursive: true });
    } catch {
        // Ignore error if directory exists
    }

    const filePath = path.join(uploadDir, uniqueFilename);
    await writeFile(filePath, buffer);

    const publicUrl = `/assets/${uniqueFilename}`;

    return new NextResponse(publicUrl, { status: 200 });

  } catch (error) {
    reportServerError('Local upload error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { headers } from 'next/headers';
import { getSupabaseClient } from '@/utils/supabase';

const isDev = process.env.NODE_ENV !== 'production';

type ProfilePost = {
  id: string;
  views?: number;
  viewedIps?: string[];
};

type ProfileData = {
  posts?: ProfilePost[];
  stats?: {
    views?: number;
    viewedIps?: string[];
  };
};

const reportServerError = (...args: unknown[]) => {
  if (isDev) {
    console.error(...args);
  }
};

export async function POST(request: Request) {
  try {
    const headersList = await headers();
    const forwardedFor = headersList.get('x-forwarded-for');
    const ip = forwardedFor ? forwardedFor.split(',')[0] : 'unknown';

    let postId: string | undefined;
    try {
      const body = await request.json();
      postId = body.postId;
    } catch {
    }

    const supabase = getSupabaseClient();
    const { data: dbData, error } = await supabase
      .from('profile_data')
      .select('content')
      .eq('id', 'main')
      .maybeSingle();

    if (error || !dbData || !dbData.content) {
      return NextResponse.json({ error: 'Profile data not found' }, { status: 404 });
    }

    const data = dbData.content as ProfileData;

    if (postId) {
      const postIndex = data.posts?.findIndex((p) => p.id === postId);
      if (typeof postIndex === 'number' && postIndex !== -1 && data.posts) {
        const post = data.posts[postIndex];
        if (!post.viewedIps) post.viewedIps = [];

        if (!post.viewedIps.includes(ip)) {
          post.views = (post.views || 0) + 1;
          post.viewedIps.push(ip);
          data.posts[postIndex] = post;
          const { error: upsertError } = await supabase.from('profile_data').upsert({ id: 'main', content: data }, { onConflict: 'id' });
          if (upsertError) console.error('Views Module - Database error:', upsertError.message);
          return NextResponse.json({ success: true, views: post.views });
        } else {
          return NextResponse.json({ success: false, error: 'Already viewed' });
        }
      }
    } else {
      if (!data.stats) {
        data.stats = { views: 0, viewedIps: [] };
      }
      if (!data.stats.viewedIps) {
        data.stats.viewedIps = [];
      }

      if (!data.stats.viewedIps.includes(ip)) {
        data.stats.views = (data.stats.views || 0) + 1;
        data.stats.viewedIps.push(ip);

        const { error: upsertError } = await supabase.from('profile_data').upsert({ id: 'main', content: data }, { onConflict: 'id' });
        if (upsertError) console.error('Views Module - Database error:', upsertError.message);
        return NextResponse.json({ success: true, views: data.stats.views });
      } else {
        return NextResponse.json({ success: false, error: 'Already viewed' });
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    reportServerError('Failed to increment views:', error);
    return NextResponse.json({ error: 'Failed to increment views' }, { status: 500 });
  }
}

