export interface ProfileRevisionMeta {
  id: string;
  createdAt: string;
  type: 'publish' | 'rollback';
}

export interface ProfileWorkflowMeta {
  revisions: ProfileRevisionMeta[];
  updatedAt: string | null;
  publishedAt: string | null;
}

import profileData from '@/data/profile.json';

const defaultProfile: ProfileData = profileData as unknown as ProfileData;

interface ProfileContextType {
  profile: ProfileData;
  workflow: ProfileWorkflowMeta;
  updateProfile: (data: Partial<ProfileData>) => Promise<void>;
  saveDraft: (data: Partial<ProfileData>) => Promise<void>;
  publishDraft: () => Promise<void>;
  rollbackToRevision: (revisionId: string) => Promise<void>;
  resetProfile: () => Promise<void>;
  refreshProfile: () => Promise<void>;
  isLoading: boolean;
}

const ProfileContext = createContext<ProfileContextType | undefined>(undefined);

export function ProfileProvider({ children }: { children: ReactNode }) {
  const [profile, setProfile] = useState<ProfileData>(defaultProfile);
  const [workflow, setWorkflow] = useState<ProfileWorkflowMeta>({
    revisions: [],
    updatedAt: null,
    publishedAt: null,
  });
  const [isLoading, setIsLoading] = useState(true);

  const applyWorkflowResponse = (nextProfile: ProfileData, nextWorkflow?: ProfileWorkflowMeta) => {
    setProfile(nextProfile);
    if (nextWorkflow) {
      setWorkflow(nextWorkflow);
    }
  };

  const performProfileAction = async (
    action: 'saveDraft' | 'publish' | 'rollback',
    payload?: Partial<ProfileData> | { revisionId: string }
  ) => {
    const body =
      action === 'saveDraft'
        ? { action, profile: payload }
        : action === 'rollback'
          ? { action, revisionId: (payload as { revisionId: string }).revisionId }
          : { action };

    const headers = new Headers();
    headers.set('Content-Type', 'application/json');

    const response = await fetch('/api/profile', {
      method: 'POST',
      headers,
      body: JSON.stringify(body),
    });

    const result = await response.json();
    if (!response.ok) {
      throw new Error(result?.error || 'Profile action failed');
    }

    applyWorkflowResponse(result.profile as ProfileData, result.workflow as ProfileWorkflowMeta);
  };

  const fetchProfile = useCallback(async () => {
    try {
      const endpoint = '/api/profile';
      const response = await fetch(endpoint);

      if (response.ok) {
        const data = await response.json();
        setProfile({ ...defaultProfile, ...(data as ProfileData) });
      }
    } catch (error) {
      console.error('Failed to fetch profile:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProfile();

    const interval = setInterval(() => {
      fetchProfile();
    }, 10000);

    return () => clearInterval(interval);
  }, [fetchProfile]);

  const refreshProfile = async () => {
    await fetchProfile();
  };

  const updateProfile = async (data: Partial<ProfileData>) => {
    setProfile((prev) => ({ ...prev, ...data }));
  };

  const saveDraft = async (data: Partial<ProfileData>) => {
    const nextDraft = { ...profile, ...data };
    setProfile(nextDraft);

    try {
      await performProfileAction('saveDraft', nextDraft);
    } catch (error) {
      console.error('Error saving profile:', error);
      throw error;
    }
  };

  const publishDraft = async () => {
    try {
      await performProfileAction('publish');
    } catch (error) {
      console.error('Error publishing draft:', error);
      throw error;
    }
  };

  const rollbackToRevision = async (revisionId: string) => {
    try {
      await performProfileAction('rollback', { revisionId });
    } catch (error) {
      console.error('Error rolling back revision:', error);
      throw error;
    }
  };

  const resetProfile = async () => {
    try {
      await saveDraft(defaultProfile);
    } catch (error) {
      console.error('Error resetting profile:', error);
      throw error;
    }
  };

  return (
    <ProfileContext.Provider
      value={{
        profile,
        workflow,
        updateProfile,
        saveDraft,
        publishDraft,
        rollbackToRevision,
        resetProfile,
        refreshProfile,
        isLoading,
      }}
    >
      {children}
    </ProfileContext.Provider>
  );
}

export function useProfile() {
  const context = useContext(ProfileContext);
  if (context === undefined) {
    throw new Error('useProfile must be used within a ProfileProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, ReactNode, useCallback } from 'react';
import { AnimatePresence } from 'framer-motion';
import Toast, { ToastType } from '@/components/Toast';

interface ToastItem {
  id: string;
  message: string;
  type: ToastType;
  duration?: number;
}

interface ToastContextType {
  showToast: (message: string, type?: ToastType, duration?: number) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([]);

  const showToast = useCallback((message: string, type: ToastType = 'info', duration?: number) => {
    const id = Date.now().toString();
    setToasts((prev) => [...prev, { id, message, type, duration }]);
  }, []);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      <div suppressHydrationWarning className="fixed bottom-6 right-6 z-[100] flex flex-col gap-2 pointer-events-none">
        <div suppressHydrationWarning className="flex flex-col gap-2 pointer-events-auto">
          <AnimatePresence mode="popLayout">
            {toasts.map((toast) => (
              <Toast
                key={toast.id}
                id={toast.id}
                message={toast.message}
                type={toast.type}
                duration={toast.duration}
                onDismiss={dismissToast}
              />
            ))}
          </AnimatePresence>
        </div>
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const context = useContext(ToastContext);
  if (context === undefined) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
}

'use client';

import React, { useEffect, useState, use } from 'react';
import Image from 'next/image';
import { useProfile } from '@/app/context/ProfileContext';
import { useToast } from '@/app/context/ToastContext';
import Link from 'next/link';
import { ArrowLeft, Heart, MessageCircle, Calendar, Eye, Share2, Reply, Send, User } from 'lucide-react';
import { motion } from 'framer-motion';
import { CustomCssInjection, MarkdownContent, estimateReadingTime, extractMarkdownHeadings, getRelatedPosts } from '@/components/ContentEnhancements';
import type { Comment } from '@/app/context/ProfileContext';

export default function PostPage({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const { profile, updateProfile, refreshProfile, isLoading } = useProfile();
  const { showToast } = useToast();
  const [commentName, setCommentName] = useState('');
  const [commentContent, setCommentContent] = useState('');
  const [replyingTo, setReplyingTo] = useState<string | null>(null);
  const [replyingToAuthor, setReplyingToAuthor] = useState<string>('');
  const post = profile.posts?.find((entry) => entry.id === resolvedParams.id) || null;
  const readingTime = post ? estimateReadingTime(post.content) : 0;
  const headings = post ? extractMarkdownHeadings(post.content) : [];
  const relatedPosts = post ? getRelatedPosts(profile.posts || [], post) : [];

  useEffect(() => {
    const incrementView = async () => {
        try {
            await fetch('/api/views', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ postId: resolvedParams.id }) 
            });
        } catch (e) {
            console.error(e);
        }
    };
    incrementView();
  }, [resolvedParams.id]);

  const maskName = (name: string) => {
    if (name.length <= 4) return name[0] + '***';
    return name.slice(0, 2) + '*****' + name.slice(-2);
  };

  const handleShare = () => {
    const url = window.location.href;
    navigator.clipboard.writeText(url).then(() => {
        showToast('Link copied to clipboard!', 'success');
    }).catch(() => {
        showToast('Failed to copy link', 'error');
    });
  };

  const handleComment = async () => {
    if (!commentContent.trim() || !post) return;

    const newComment = {
        id: Date.now().toString(),
        author: commentName.trim() || 'Anonymous',
        content: commentContent.trim(),
        date: new Date().toISOString(),
        replies: []
    };

    const postIndex = profile.posts.findIndex(p => p.id === post.id);
    if (postIndex === -1) return;

    const newPosts = [...profile.posts];
    const currentPost = { ...newPosts[postIndex] };

    if (replyingTo) {
        const commentIndex = currentPost.comments.findIndex((c: Comment) => c.id === replyingTo);
        if (commentIndex !== -1) {
            const updatedComments = [...currentPost.comments];
            updatedComments[commentIndex] = {
                ...updatedComments[commentIndex],
                replies: [...(updatedComments[commentIndex].replies || []), newComment]
            };
            currentPost.comments = updatedComments;
        }
    } else {
        currentPost.comments = [...(currentPost.comments || []), newComment];
    }

    newPosts[postIndex] = currentPost;

    updateProfile({ posts: newPosts });

    setCommentContent('');
    setCommentName('');
    setReplyingTo(null);
    setReplyingToAuthor('');
    showToast('Comment posted!', 'success');
  };

  const handleLike = async () => {
    if (!post) return;

    const postIndex = profile.posts.findIndex(p => p.id === post.id);
    if (postIndex === -1) return;

    const newPosts = [...profile.posts];
    newPosts[postIndex] = { ...newPosts[postIndex], likes: (newPosts[postIndex].likes || 0) + 1 };

    updateProfile({ posts: newPosts });

    try {
        const res = await fetch('/api/like', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ postId: post.id })
        });

        const data = await res.json();

        if (!res.ok) {
            if (data.error === 'Already liked') {
                showToast('You have already liked this post!', 'info');
            } else {
                showToast('Like failed', 'error');
            }
            refreshProfile();
            return;
        }
        showToast('Post liked!', 'success');
    } catch (error) {
        console.error(error);
    }
  };

  if (isLoading) return <div className="min-h-screen bg-black text-white flex items-center justify-center"><div className="animate-spin rounded-full h-8 w-8 border-t-2 border-indigo-500"></div></div>;

  if (!post) {
    return (
      <div className="min-h-screen bg-black text-white flex flex-col items-center justify-center gap-4">
        <h1 className="text-2xl font-bold">Post not found</h1>
        <Link href="/" className="px-4 py-2 bg-white/10 rounded-lg hover:bg-white/20 transition-colors">
            Return Home
        </Link>
      </div>
    );
  }

  return (
    <div 
        className="min-h-screen bg-black text-white relative overflow-hidden select-none"
        onContextMenu={(e) => e.preventDefault()}
    >
        <CustomCssInjection css={profile.customCss} />
        <div className="fixed inset-0 pointer-events-none z-0 opacity-20"
             style={{ 
                 backgroundImage: `url(${post.imageUrl || profile.theme.backgroundImageUrl})`,
                 backgroundSize: 'cover',
                 backgroundPosition: 'center',
                 filter: `blur(${profile.theme.enterScreenBlur}px)`
             }} 
        />
        <div className="fixed inset-0 bg-black/60 z-0 pointer-events-none" />

        <div className="relative z-10 max-w-4xl mx-auto p-4 md:p-8">
            <Link href="/" className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-8 transition-colors bg-black/40 px-4 py-2 rounded-full border border-white/10 hover:border-white/30 backdrop-blur-md">
                <ArrowLeft size={18} />
                <span>Back to Profile</span>
            </Link>

            <motion.article 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-[#111]/80 backdrop-blur-xl rounded-3xl border border-white/10 overflow-hidden shadow-2xl"
            >
                {post.imageUrl && (
                    <div className="w-full h-64 md:h-96 relative">
                        <Image src={post.imageUrl} alt={post.title} fill className="object-cover" sizes="(max-width: 768px) 100vw, 896px" />
                        <div className="absolute inset-0 bg-linear-to-t from-[#111] to-transparent" />
                    </div>
                )}

                <div className="p-6 md:p-10 space-y-6">
                    <div className="space-y-4">
                        <h1 className="text-3xl md:text-5xl font-bold text-white tracking-tight">{post.title}</h1>
                        <div className="flex flex-wrap gap-4 text-sm text-gray-400">
                            <span className="flex items-center gap-1.5"><Calendar size={14} /> {new Date(post.date).toLocaleDateString()}</span>
                            <span className="flex items-center gap-1.5"><Eye size={14} /> {post.views || 0} views</span>
                            <span className="flex items-center gap-1.5"><Heart size={14} /> {post.likes || 0} likes</span>
                            <span className="rounded-full border border-white/10 bg-white/5 px-2 py-1 text-xs">{readingTime} min read</span>
                            {post.category && <span className="rounded-full border border-white/10 bg-white/5 px-2 py-1 text-xs">{post.category}</span>}
                        </div>
                        {post.tags && post.tags.length > 0 && (
