'use client';
import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import { useToast } from '@/app/context/ToastContext';

export default function SetupPage() {
  const [supabaseUrl, setSupabaseUrl] = useState('');
  const [supabaseKey, setSupabaseKey] = useState('');
  const [adminUsername, setAdminUsername] = useState('');
  const [adminPassword, setAdminPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [sqlRequired, setSqlRequired] = useState(false);
  const [sqlToRun, setSqlToRun] = useState('');
  const router = useRouter();
  const { showToast } = useToast();

  const handleSetup = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await fetch('/api/setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ supabaseUrl, supabaseKey, adminUsername, adminPassword })
      });

      const data = await res.json();

      if (res.ok) {
        if (data.sqlRequired) {
           setSqlRequired(true);
           setSqlToRun(data.sql);
           showToast(data.message || 'SQL setup required to complete.', 'info');
        } else {
           showToast('Setup Complete! Logging into admin...', 'success');
           setLoading(false);
           document.cookie = `adminSecure=true; path=/; max-age=3600; SameSite=Strict`;
           router.push('/admin');
        }
      } else {
        throw new Error(data.error || 'Failed to setup');
      }
    } catch (e) {
      showToast('Network error during setup', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center text-white p-4">
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#111] p-8 rounded-2xl max-w-md w-full border border-white/10 shadow-2xl">
        <h1 className="text-2xl font-bold mb-2">First Run Setup</h1>
        <p className="text-gray-400 text-sm mb-6">Initialize your Supabase connection and create an admin account to get started.</p>

        <form onSubmit={handleSetup} className="space-y-4">
          <div>
            <label className="block text-sm text-gray-400 mb-1">Supabase URL</label>
            <input required type="url" value={supabaseUrl} onChange={e => setSupabaseUrl(e.target.value)} className="w-full bg-black border border-white/10 rounded-lg px-4 py-2 outline-none focus:border-indigo-500" placeholder="https://xyz.supabase.co" />
          </div>
          <div>
            <label className="block text-sm text-gray-400 mb-1">Supabase Service Key / Anon Key</label>
            <input required type="password" value={supabaseKey} onChange={e => setSupabaseKey(e.target.value)} className="w-full bg-black border border-white/10 rounded-lg px-4 py-2 outline-none focus:border-indigo-500" placeholder="eyJhb..." />
          </div>
          <div className="pt-4 border-t border-white/10">
            <label className="block text-sm text-gray-400 mb-1">Admin Username</label>
            <input required type="text" value={adminUsername} onChange={e => setAdminUsername(e.target.value)} className="w-full bg-black border border-white/10 rounded-lg px-4 py-2 outline-none focus:border-indigo-500" />
          </div>
          <div>
            <label className="block text-sm text-gray-400 mb-1">Admin Password</label>
            <input required type="password" value={adminPassword} onChange={e => setAdminPassword(e.target.value)} className="w-full bg-black border border-white/10 rounded-lg px-4 py-2 outline-none focus:border-indigo-500" />
          </div>

          {!sqlRequired ? (
            <button disabled={loading} type="submit" className="w-full bg-indigo-600 hover:bg-indigo-500 text-white py-3 rounded-lg font-bold mt-4 disabled:opacity-50 transition-colors">
              {loading ? 'Initializing...' : 'Complete Setup'}
            </button>
          ) : (
            <div className="mt-4 p-4 bg-yellow-900/30 border border-yellow-500/50 rounded-lg">
              <h3 className="text-yellow-400 font-bold mb-2">Supabase SQL Editor - Data Configuration Required:</h3>
              <p className="text-gray-300 text-sm mb-3">Copy the SQL code below, paste it into the "SQL Editor" tab in your Supabase Dashboard, and click RUN to create the data table for your website.</p>
              <textarea
                readOnly
                className="w-full h-40 bg-black text-green-400 p-3 rounded font-mono text-sm border-white/10 border"
                value={sqlToRun}
              />
              <button 
                type="button" 
                onClick={() => {
                  showToast('Copied! Please come back here and click complete after running it.', 'info');
                  navigator.clipboard.writeText(sqlToRun);
               }} 
                className="mt-2 w-full bg-gray-700 hover:bg-gray-600 py-2 rounded text-white font-mono"
              >
                  Copy & Wait for Database
              </button>
              <button 
                type="button"
                onClick={() => {
                   setSqlRequired(false);
                   document.cookie = `adminSecure=true; path=/; max-age=3600; SameSite=Strict`;
                   router.push('/admin');
                }}
                className="mt-4 w-full bg-indigo-600 hover:bg-indigo-500 py-2 rounded text-white font-bold"
              >
                  SQL execution complete - Enter Admin!
              </button>
            </div>
          )}
        </form>
      </motion.div>
    </div>
  );
}

'use client';

import React, { useEffect, useRef } from 'react';
import { useProfile } from '@/app/context/ProfileContext';
import { usePerformanceMode } from '@/hooks/usePerformanceMode';

export default function BackgroundEffects() {
  const { profile } = useProfile();
  const { mode, isMinimal } = usePerformanceMode();
  const effect = profile.theme?.backgroundEffect || 'noise';
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (effect !== 'rain' && effect !== 'snow') return;
    if (isMinimal) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let lastFrameTime = 0;
    let particles: Array<{ x: number; y: number; speed: number; length?: number; size?: number }> = [];
    const targetFps = mode === 'balanced' ? 30 : 60;
    const frameDuration = 1000 / targetFps;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    const createParticles = () => {
      particles = [];
      const count = effect === 'rain'
        ? mode === 'balanced' ? 55 : 90
        : mode === 'balanced' ? 30 : 50;
      for (let i = 0; i < count; i++) {
        particles.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          speed: Math.random() * (effect === 'rain' ? 15 : 2) + (effect === 'rain' ? 10 : 1),
          length: Math.random() * 20 + 10,
          size: Math.random() * 3 + 2,
        });
      }
    };

    const draw = (timestamp: number) => {
      if (!ctx || !canvas) return;

      if (document.hidden) {
        animationFrameId = requestAnimationFrame(draw);
        return;
      }

      if (timestamp - lastFrameTime < frameDuration) {
        animationFrameId = requestAnimationFrame(draw);
        return;
      }

      lastFrameTime = timestamp;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
      ctx.lineWidth = 1;

      particles.forEach((p) => {
        if (effect === 'rain') {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(p.x, p.y + (p.length || 10));
          ctx.stroke();
          p.y += p.speed;
          if (p.y > canvas.height) {
            p.y = -20;
            p.x = Math.random() * canvas.width;
          }
        } else {
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size || 2, 0, Math.PI * 2);
          ctx.fill();
          p.y += p.speed;
          p.x += Math.sin(p.y * 0.01) * 0.5;
          if (p.y > canvas.height) {
            p.y = -5;
            p.x = Math.random() * canvas.width;
          }
        }
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    resize();
    createParticles();
    animationFrameId = requestAnimationFrame(draw);

    window.addEventListener('resize', resize);

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [effect, isMinimal, mode]);

  return (
    <>
      {effect === 'noise' && <div className="noise-bg" />}
      {!isMinimal && <div className="fixed inset-0 pointer-events-none z-[100] crt" />}
      {!isMinimal && (effect === 'rain' || effect === 'snow') && (
        <canvas ref={canvasRef} className="fixed inset-0 pointer-events-none z-0" />
      )}
    </>
  );
}

'use client';

import { useEffect } from 'react';
import { usePerformanceMode } from '@/hooks/usePerformanceMode';

type SparkleAnimationParams = {
  translateX: number;
  translateY: number;
  scale: [number, number];
  opacity: [number, number];
  duration: number;
  easing: string;
  complete: () => void;
};

type SparkleAnimator = (targets: HTMLElement, params: SparkleAnimationParams) => unknown;

const sparklePalette = ['#FFD700', '#FF69B4', '#00FFFF', '#FFFFFF'];

const ClickSparkle = () => {
  const { isMinimal, isBalanced } = usePerformanceMode();

  useEffect(() => {
    if (isMinimal) {
      return;
    }

    let animateSparkle: SparkleAnimator | null = null;
    let destroyed = false;

    const setupAnime = async () => {
      const animeImport = await import('animejs');
      animateSparkle = animeImport.animate as unknown as SparkleAnimator;
    };

    setupAnime();

    const handleClick = (e: MouseEvent) => {
      if (!animateSparkle || destroyed) {
        return;
      }

      const sparkleCount = isBalanced ? 4 : 7;

      for (let index = 0; index < sparkleCount; index += 1) {
        const sparkle = document.createElement('span');
        const color = sparklePalette[Math.floor(Math.random() * sparklePalette.length)];

        sparkle.style.position = 'fixed';
        sparkle.style.left = `${e.clientX}px`;
        sparkle.style.top = `${e.clientY}px`;
        sparkle.style.width = '6px';
        sparkle.style.height = '6px';
        sparkle.style.borderRadius = '9999px';
        sparkle.style.pointerEvents = 'none';
        sparkle.style.backgroundColor = color;
        sparkle.style.boxShadow = `0 0 8px ${color}`;
        sparkle.style.zIndex = '9999';
        document.body.appendChild(sparkle);

        animateSparkle(sparkle, {
          translateX: (Math.random() - 0.5) * 70,
          translateY: (Math.random() - 0.5) * 70,
          scale: [1, 0],
          opacity: [1, 0],
          duration: isBalanced ? 420 : 620,
          easing: 'easeOutQuad',
          complete: () => {
            sparkle.remove();
          },
        });
      }
    };

    window.addEventListener('click', handleClick);
    return () => {
      destroyed = true;
      window.removeEventListener('click', handleClick);
    };
  }, [isBalanced, isMinimal]);

  return null;
};

export default ClickSparkle;

'use client';

import React, { useState, useEffect } from 'react';

interface ClockProps {
  timezone: string;
  format: string;
}

const Clock: React.FC<ClockProps> = ({ timezone, format }) => {
  const [time, setTime] = useState('');

  useEffect(() => {
    const updateTime = () => {
      try {
        const now = new Date();
        const options: Intl.DateTimeFormatOptions = {
          timeZone: timezone || 'UTC',
          hour12: false,
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        };

        const formatter = new Intl.DateTimeFormat('en-US', options);
        const parts = formatter.formatToParts(now);
        const getPart = (type: string) => parts.find(p => p.type === type)?.value || '00';

        let formatted = format;
        formatted = formatted.replace('HH', getPart('hour'));
        formatted = formatted.replace('hh', getPart('hour'));
        formatted = formatted.replace('mm', getPart('minute'));
        formatted = formatted.replace('ss', getPart('second'));

        setTime(formatted);
      } catch (e) {
        setTime('--:--');
      }
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, [timezone, format]);

  return <span>{time}</span>;
};

export default Clock;

