                            <span className={`px-1.5 py-0.5 rounded text-[10px] ${file.source === 'local' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-indigo-500/20 text-indigo-400'}`}>
                                {file.source === 'local' ? 'Local' : 'Cloud'}
