export interface LanyardData {
  discord_status: 'online' | 'idle' | 'dnd' | 'offline';
  active_on_discord_mobile?: boolean;
  active_on_discord_web?: boolean;
  active_on_discord_desktop?: boolean;
  activities: Array<{
    name: string;
    state?: string;
    details?: string;
    assets?: {
      large_image?: string;
      small_image?: string;
    };
    emoji?: {
      name: string;
      id?: string;
      animated?: boolean;
    };
    timestamps?: {
      start?: number;
      end?: number;
    };
    application_id?: string;
    type: number;
    created_at: number;
  }>;
  discord_user: {
    username: string;
    discriminator: string;
    id: string;
    avatar: string;
    public_flags: number;
  };
  kv?: Record<string, string>;
  listening_to_spotify: boolean;
  spotify?: {
    track_id: string;
    timestamps: {
      start: number;
      end: number;
    };
    song: string;
    artist: string;
    album_art_url: string;
    album: string;
  };
  primary_guild?: {
    badge: string;
    identity_enabled: boolean;
    identity_guild_id: string;
    tag: string;
  };
}

interface LanyardMessage {
  op: number;
  d: unknown;
  t?: string;
}

export function useLanyard(discordId?: string) {
  const [data, setData] = useState<LanyardData | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!discordId) {
      setData(null);
      setError(null);
      return;
    }

    let socket: WebSocket | null = null;
    let heartbeatInterval: NodeJS.Timeout | null = null;

    const connect = () => {
      socket = new WebSocket('wss://api.lanyard.rest/socket');

      socket.onopen = () => {
        reportClientInfo('Lanyard WebSocket connected');
      };

      socket.onmessage = (event) => {
        try {
          const message: LanyardMessage = JSON.parse(event.data);

          switch (message.op) {
            case 1:
              socket?.send(JSON.stringify({
                op: 2,
                d: { subscribe_to_id: discordId }
              }));

              if (heartbeatInterval) clearInterval(heartbeatInterval);
              heartbeatInterval = setInterval(() => {
                socket?.send(JSON.stringify({ op: 3 }));
              }, (message.d as { heartbeat_interval: number }).heartbeat_interval);
              break;

            case 0:
              if (message.t === 'INIT_STATE' || message.t === 'PRESENCE_UPDATE') {
                setData(message.d as LanyardData);
                setError(null);
              }
              break;
          }
        } catch (err) {
          reportClientError('Error parsing Lanyard message:', err);
        }
      };

      socket.onclose = () => {
        reportClientInfo('Lanyard WebSocket closed');
        if (heartbeatInterval) clearInterval(heartbeatInterval);
        setTimeout(connect, 5000);
      };

      socket.onerror = (err) => {
        reportClientError('Lanyard WebSocket error:', err);
        setError('Connection failed');
      };
    };

    const fetchInitial = async () => {
      try {
        const res = await fetch(`https://api.lanyard.rest/v1/users/${discordId}`);
        const json = await res.json();
        if (json.success) {
          setData(json.data);
          setError(null);
        }
      } catch (err) {
        reportClientError('Initial Lanyard fetch failed:', err);
      }
    };

    fetchInitial();
    connect();

    return () => {
      if (heartbeatInterval) clearInterval(heartbeatInterval);
      if (socket) socket.close();
    };
  }, [discordId]);

  const loading = Boolean(discordId) && data === null && error === null;

  return { data, loading, error };
}

'use client';

import { useEffect, useMemo, useState } from 'react';

export type PerformanceMode = 'full' | 'balanced' | 'minimal';

const detectPerformanceMode = (): PerformanceMode => {
  if (typeof window === 'undefined') {
    return 'balanced';
  }

  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const runtimeNavigator = navigator as Navigator & {
    connection?: { saveData?: boolean };
    deviceMemory?: number;
  };

  const saveData = runtimeNavigator.connection?.saveData === true;
  const hardwareConcurrency = navigator.hardwareConcurrency ?? 4;
  const deviceMemory = runtimeNavigator.deviceMemory ?? 4;

  if (reducedMotion || saveData || hardwareConcurrency <= 4 || deviceMemory <= 4) {
    return 'minimal';
  }

  if (hardwareConcurrency <= 6 || deviceMemory <= 8) {
    return 'balanced';
  }

  return 'full';
};

export const usePerformanceMode = () => {
  const [mode, setMode] = useState<PerformanceMode>('balanced');

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

    const updateMode = () => {
      setMode(detectPerformanceMode());
    };

    updateMode();
    mediaQuery.addEventListener('change', updateMode);

    return () => {
      mediaQuery.removeEventListener('change', updateMode);
    };
  }, []);

  return useMemo(
    () => ({
      mode,
      isMinimal: mode === 'minimal',
      isBalanced: mode === 'balanced',
      isFull: mode === 'full',
    }),
    [mode]
  );
};

import fs from 'fs';
import path from 'path';
import os from 'os';

export function getConfigPath() {
    const isWin = process.platform === 'win32';
    const configDir = isWin
        ? path.join(process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'), 'aura-profile')
        : path.join(os.homedir(), '.config', 'aura-profile');

    return path.join(configDir, 'config.json');
}

export function getConfig() {
    try {
        const configPath = getConfigPath();
        if (fs.existsSync(configPath)) {
            const data = fs.readFileSync(configPath, 'utf-8');
            return JSON.parse(data);
        }
    } catch (e) {
        console.error('Failed to read aura-profile config:', e);
    }
    return null;
}

export function saveConfig(config: any) {
    const configPath = getConfigPath();
    const configDir = path.dirname(configPath);
    if (!fs.existsSync(configDir)) {
        fs.mkdirSync(configDir, { recursive: true });
    }
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2), 'utf-8');
}

import { createClient } from '@supabase/supabase-js';
import { getConfig } from './config';

export function getSupabaseClient() {
  const config = getConfig();
  if (!config || !config.NEXT_PUBLIC_SUPABASE_URL || !config.NEXT_PUBLIC_SUPABASE_ANON_KEY) {
    throw new Error('Supabase is not configured yet');
  }

  return createClient(config.NEXT_PUBLIC_SUPABASE_URL, config.NEXT_PUBLIC_SUPABASE_ANON_KEY);
}
